// Агрегація воронки продажів для AI-звіту (Run Once for All Items)
const deals = $input.all().map(i => i.json);
const today = new Date();
today.setHours(0, 0, 0, 0);

const CLOSED = ['Closed Won', 'Closed Lost', 'Closed Lost to Competition'];
const LATE_STAGES = ['Proposal/Price Quote', 'Negotiation/Review'];
const STAGE_ORDER = ['Qualification', 'Needs Analysis', 'Value Proposition', 'Identify Decision Makers',
  'Proposal/Price Quote', 'Negotiation/Review', 'Closed Won', 'Closed Lost', 'Closed Lost to Competition'];

const byStage = {};
let totalPipeline = 0;
let atRiskAmount = 0;
const problemDeals = [];

for (const d of deals) {
  const stage = d.Stage || 'Unknown';
  const amount = Number(d.Amount) || 0;
  if (!byStage[stage]) byStage[stage] = { stage, count: 0, amount: 0 };
  byStage[stage].count += 1;
  byStage[stage].amount += amount;

  if (CLOSED.includes(stage)) continue;
  totalPipeline += amount;

  // Сигнали ризику — тільки прапорці, без деталей: деталі агент отримує через Tool
  const flags = [];
  let daysOverdue = 0;
  if (d.Closing_Date) {
    const close = new Date(d.Closing_Date);
    daysOverdue = Math.floor((today - close) / 86400000);
    if (daysOverdue > 0) flags.push(`дата закриття прострочена на ${daysOverdue} дн.`);
  }
  if (!d.Next_Step) flags.push('не вказано наступний крок');
  if (LATE_STAGES.includes(stage) && (Number(d.Probability) || 0) <= 50) flags.push('низька ймовірність на пізній стадії');

  if (flags.length) {
    atRiskAmount += amount;
    problemDeals.push({ deal_id: d.id, deal_name: d.Deal_Name, stage, amount, flags });
  }
}

const stages = Object.values(byStage).sort((a, b) => STAGE_ORDER.indexOf(a.stage) - STAGE_ORDER.indexOf(b.stage));

return [{
  json: {
    report_date: today.toISOString().slice(0, 10),
    total_deals: deals.length,
    open_deals: deals.filter(d => !CLOSED.includes(d.Stage)).length,
    total_pipeline: totalPipeline,
    at_risk_amount: atRiskAmount,
    currency: 'UAH',
    stages,
    problem_deals: problemDeals.sort((a, b) => b.amount - a.amount),
  },
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "headline": {
      "type": "string",
      "description": "1-2 речення: загальний стан воронки сьогодні"
    },
    "bottleneck_stage": {
      "type": "string",
      "description": "Стадія, де зависає найбільша сума проблемних угод"
    },
    "problem_deals": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "deal_id": { "type": "string" },
          "deal_name": { "type": "string" },
          "stage": { "type": "string" },
          "amount": { "type": "number" },
          "risk_level": { "type": "string", "enum": ["high", "medium"] },
          "problem": { "type": "string" },
          "recommendation": { "type": "string" }
        },
        "required": ["deal_id", "deal_name", "stage", "amount", "risk_level", "problem", "recommendation"]
      }
    },
    "top_actions": {
      "type": "array",
      "items": { "type": "string" },
      "minItems": 3,
      "maxItems": 3
    }
  },
  "required": ["headline", "bottleneck_stage", "problem_deals", "top_actions"]
}

parameters.text:
={{ (() => {
  const d = $('Агрегація воронки').first().json;
  const o = $json.output;
  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const money = n => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' грн';
  const pct = d.total_pipeline ? Math.round(d.at_risk_amount / d.total_pipeline * 100) : 0;
  const lines = [];
  lines.push('📊 <b>ЩОДЕННИЙ ЗВІТ ПО ВОРОНЦІ</b>');
  lines.push('📅 ' + d.report_date.split('-').reverse().join('.'));
  lines.push('');
  lines.push(esc(o.headline));
  lines.push('');
  lines.push('<b>💼 Угоди по стадіях</b> (усього ' + d.total_deals + ')');
  d.stages.forEach(s => lines.push('• ' + esc(s.stage) + ' — <b>' + s.count + '</b> · ' + money(s.amount)));
  lines.push('');
  lines.push('<b>💰 Гроші</b>');
  lines.push('Відкрита воронка: <b>' + money(d.total_pipeline) + '</b> (' + d.open_deals + ' угод)');
  lines.push('⚠️ Під ризиком: <b>' + money(d.at_risk_amount) + '</b> (' + pct + '%)');
  lines.push('🔻 Вузьке місце: <b>' + esc(o.bottleneck_stage) + '</b>');
  lines.push('');
  lines.push('<b>🚨 Проблемні угоди (' + o.problem_deals.length + ')</b>');
  o.problem_deals.forEach(p => {
    lines.push('');
    lines.push((p.risk_level === 'high' ? '🔴 ' : '🟡 ') + '<a href="https://crm.zoho.eu/crm/tab/Potentials/' + p.deal_id + '">' + esc(p.deal_name) + '</a>');
    lines.push('<i>' + esc(p.stage) + ' · ' + money(p.amount) + '</i>');
    lines.push('Проблема: ' + esc(p.problem));
    lines.push('👉 ' + esc(p.recommendation));
  });
  lines.push('');
  lines.push('<b>✅ Що зробити сьогодні</b>');
  o.top_actions.forEach((a, i) => lines.push((i + 1) + '. ' + esc(a)));
  return lines.join('\n');
})() }}
